select * from public.cafe_sales;


-- A. Revenue and sales

-- 1. What is the total revenue generated by the café?

select sum(revenue) as total_revenue
from public.cafe_sales;

-- # 2. What is the average transaction value?

select round(avg(revenue), 2) as avg_transaction_value
from public.cafe_sales;

-- 3. How many transactions were recorded?

select count(*) as total_transactions from public.cafe_sales;

-- 4. What is the total quantity of items sold?

select sum(quantity) as total_quantity_sold
from public.cafe_sales;



-- B. Time-based analysis

-- 1. Which month has the highest sales?

select year_month, sum(revenue) as total_sales from public.cafe_sales
group by year_month
order by total_sales desc
limit 1;

-- 2. Which weekday has the highest sales?

SELECT weekday, SUM(revenue) AS total_sales
FROM public.cafe_sales
GROUP BY weekday
ORDER BY total_sales DESC
LIMIT 1;

-- 3. How does sales performance change over time?

SELECT year_month, SUM(revenue) AS total_sales, COUNT(*) AS total_transactions
FROM public.cafe_sales
WHERE year_month IS NOT NULL
GROUP BY year_month
ORDER BY year_month;


-- C. Product analysis

-- 1. Which item generates the most revenue?

SELECT item, SUM(revenue) AS total_revenue
FROM public.cafe_sales
WHERE item <> 'Unknown'
GROUP BY item
ORDER BY total_revenue DESC
LIMIT 1;

-- 2. Which item sells the highest quantity?

SELECT item, SUM(quantity) AS total_quantity_sold
FROM public.cafe_sales
WHERE item <> 'Unknown'
GROUP BY item
ORDER BY total_quantity_sold DESC
LIMIT 1;

-- 3. Which items have the highest average selling price?

SELECT item, ROUND(AVG(price_per_unit), 2) AS avg_selling_price
FROM public.cafe_sales
WHERE item <> 'Unknown'
GROUP BY item
ORDER BY avg_selling_price DESC;


-- D. Payment and location analysis

-- 1. Which payment method is used most frequently?

SELECT payment_method, COUNT(*) AS total_transactions
FROM public.cafe_sales
WHERE payment_method <> 'Unknown'
GROUP BY payment_method
ORDER BY total_transactions DESC
LIMIT 1;

-- 2. Which location type generates the most sales: In-store or Takeaway?

SELECT location, SUM(revenue) AS total_sales
FROM public.cafe_sales
WHERE location IN ('In-store', 'Takeaway')
GROUP BY location
ORDER BY total_sales DESC;

-- 3. How does the average transaction value differ by location?

select location, round(avg(revenue),2) as avg_transaction
from public.cafe_sales
where location <> 'Unknown'
group by location;
